window.NOTES={"version":51,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":6,"chapter":3,"section":"3.2","type":"单选","topic":"文档视图","title":"Word视图、标题结构与导航窗格","trigger":"真题从视图用途、标题重组和导航窗格无标题的故障现象考查长文档结构。","conclusion":"先给正文标题建立层级，再用大纲视图组织内容、导航窗格定位标题，最后用打印布局核对实际页面。只放大、加粗文字不会建立标题结构。","points":["建立层级：给一级、二级标题分别应用“标题1”“标题2”；自定义标题可设置相应大纲级别。不要把整篇标题都设为同一级。","导航窗格：视图→导航窗格→标题。单击标题定位；在标题列表中拖动标题可连同所属内容调整顺序。表格、文本框、页眉和页脚中的标题不在这个列表中。","自动目录：引用→目录。默认自动目录依据标题层级生成；自定义目录还可配置样式、大纲级别或目录条目。","目录更新：只改变分页时可更新页码；新增、删除或改名标题后应更新整个目录。直接编辑目录显示文字不能替代修改正文标题。","草稿视图侧重文字，不显示图片、页眉页脚；桌面Word的Web版式仍可编辑文字和查看图片，不按纸张分页。不要把Web版式误当成只读网页。","误删文字后按Ctrl+Z撤消；撤消后要恢复该动作可按Ctrl+Y。没有待恢复动作时，Ctrl+Y或F4可用于重复受支持的上一操作，效果取决于当前状态。","教学示例：删除一段→Ctrl+Z恢复该段→Ctrl+Y再次删除。保存文件等动作不一定能够撤消，不能把快捷键当作任何操作的通用回退。","要逐段核对两份文档，先打开两文件→视图→并排查看；开启“同步滚动”可一起翻动，关闭后可分别滚动。并排查看只改变显示方式，不自动合并两份内容。"],"boundary":"导航窗格、正文标题和自动目录是相关的三个对象；某处看起来像标题，不能保证它会被导航或目录收录。","id":"merged-5","sources":[{"year":2020,"q":6,"type":"单选"},{"year":2023,"q":8,"type":"单选"},{"year":2023,"q":66,"type":"分析"},{"year":2026,"q":27,"type":"多选"},{"year":2021,"q":41,"type":"操作","page":6},{"year":2021,"q":45,"type":"操作","page":7},{"year":2021,"q":46,"type":"操作","page":7}],"keys":["2020-6","2023-8","2023-66","2026-27","2021-41","2021-45","2021-46"],"comparison":{"headers":["视图","主要用途","查看页面效果"],"rows":[["打印布局","编辑文档并检查分页、页眉页脚","适合核对打印版式"],["大纲视图","按标题级别升降级、重排内容","重在文档结构"],["草稿视图","集中编辑正文","不显示图片、页眉页脚和完整页面版式"],["Web版式","按网页连续显示，仍可编辑","不按纸张正常分页"],["阅读模式","以屏幕阅读为主","阅读显示不改变文档格式"]]},"searchAliases":["目录不显示标题","导航没有标题","标题不进目录","目录页码不对"],"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"导航和自动目录依赖真实标题样式；需要统一外观时应修改对应样式定义。"},{"id":"y2022q72","label":"Word标题层级决定导入PowerPoint后的幻灯片结构","reason":"同一套Word标题层级还决定从大纲导入PowerPoint时的幻灯片和正文归属。"},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"普通目录依据标题，图表目录依据题注，可对照理解自动目录各自的结构来源。"}],"pointGroups":[{"title":"建立标题层级并导航","indices":[0,1]},{"title":"生成与更新自动目录","indices":[2,3]},{"title":"按任务选择文档视图","indices":[4]},{"title":"撤消恢复看操作历史，并排查看看窗口关系","indices":[5,6,7]}]},{"id":"syllabus-word-text-editing","chapter":3,"section":"3.2","origin":"syllabus","type":"知识补充","topic":"输入与剪贴板","title":"正文编辑：先定位和选择，再输入、复制或移动","conclusion":"插入点决定输入位置，选区决定被替换或处理的内容；复制保留原文，剪切后原文先移除，粘贴把内容放到新的插入位置。","points":["先单击正文放置插入点，再输入文字。插入模式下，新文字推开后面的内容；已有选区时，直接输入通常替换选中文字。开始改稿前先确认是否仍有高亮选区，不能把“有光标”理解为一定没有选择。","没有选中文字时，Backspace删除插入点前的内容，Delete删除后面的内容；已有选区时，两者都可删除所选文本。若删除的是段落标记，原先两个段落会合并，应检查合并后的段落格式；不要把表格中删除内容与删除结构的规则套到普通正文。","改写模式会用新输入覆盖后面的已有文字。Word2016中，文件→选项→高级→编辑选项可设置“使用改写模式”；只有启用“用Insert键控制改写模式”时，Insert才按这一设置切换。不是每台Word按一次Insert都会改写。","复制文字：选中源文字→Ctrl+C（或开始→剪贴板→复制）→单击目标位置→Ctrl+V→核对两处文字。移动文字：选中→Ctrl+X剪切→确定目标位置→Ctrl+V→核对新位置和原位置。正文文本剪切通常立即从编辑区移除，与资源管理器先把文件标记为待移动的时机不同。","也可先选中文字，指向选区后左键拖到目标插入位置来移动，按住Ctrl拖动来复制；要观察插入标记和复制提示。此操作受Word“允许拖放式文字编辑”等设置影响，不能把Windows文件跨卷拖放的默认规则套到正文。手机网页的长按选词与桌面Word鼠标选区不是同一交互。","粘贴后核对内容及格式。“保留源格式”保留复制处格式；“合并格式”采用目标样式，但可能保留原文局部加粗、倾斜等强调；“只保留文本”舍弃原字符格式及图形，文字仍按目标位置格式显示，不是完全没有格式，也不能保留图片或完整表格外观。Word2016的Ctrl+Shift+V用于粘贴格式，不应按新版Microsoft365的纯文本粘贴快捷键记忆。","开始→剪贴板组的对话框启动器可打开Office剪贴板，最多收集24项，可选择其中一项粘贴，也可全部粘贴或清空。继续收集超出容量时会移走最早项目；它与Windows的当前剪贴板及Win+V历史不是同一个列表。普通粘贴不会自动清空所复制的文本，可再次粘贴；不要把它当长期保存文稿的方式。","需要撤销最近编辑时按Ctrl+Z，先观察是否撤回了目标动作；撤销后可用Ctrl+Y重做仍可重做的动作。重做与重复当前命令有不同语境，撤销栈也不是永久版本备份；重要改动前保存文档，不能假定任何操作都可无限撤销。","输入键盘上没有的字符，可用插入→符号→其他符号，选择字体和字符后插入；能否显示取决于字体支持。插入一个带圈数字是字符内容，不会自动建立可连续编号的段落列表。"],"boundary":"本卡讲普通可编辑正文；表格、受保护区域、域与图形对象另有操作边界。选区和键盘移动练习见关联卡片；网页不模拟系统剪贴板或完整Word编辑器。","sources":[],"keys":[],"searchAliases":["插入点","选区替换","Delete","Backspace","改写模式","Insert","Office剪贴板","24项","只保留文本","Ctrl+X"],"trigger":"按2026年考试要求与已核查课堂范围补充；操作以Windows桌面Word2016为基线，具体来源见参考资料。网页演示不等于真实Word实测。","pointGroups":[{"title":"输入、删除与改写","indices":[0,1,2]},{"title":"复制、移动与粘贴的完整链","indices":[3,4,5]},{"title":"剪贴板、撤销与特殊字符","indices":[6,7,8]}],"related":[{"id":"y2024q7","label":"练习真实文本选区","reason":"单击定位、拖选并比较行首行末与文首文末。"},{"id":"y2025q48","label":"批量改词与格式","reason":"从单次修改过渡到核对查找条件后批量处理。"}],"pointPresentation":{"3":{"title":"复制与移动文字","navigationLabel":"复制与移动","blocks":[{"label":"复制：保留原文","steps":["复制文字：选中源文字","Ctrl+C","单击目标位置","Ctrl+V","核对两处文字"]},{"label":"移动：改变文字位置","from":"移动文字：","steps":["移动文字：选中","Ctrl+X","确定目标位置","Ctrl+V","核对新位置"]},{"label":"剪切后发生什么","from":"正文文本剪切"}]},"4":{"title":"用鼠标拖动文字","navigationLabel":"拖动文字","blocks":[{"label":"操作方式"},{"label":"设置条件与区别","from":"此操作受"},{"from":"手机网页","role":"demo"}]},"5":{"title":"三种粘贴格式","navigationLabel":"粘贴与格式","blocks":[{},{"label":"保留源格式","from":"“保留源格式”"},{"label":"合并格式","from":"“合并格式”"},{"label":"只保留文本","from":"“只保留文本”"},{"label":"Word2016快捷键","from":"Word2016"}]},"6":{"title":"Office剪贴板","navigationLabel":"Office剪贴板","blocks":[{"label":"入口与用途"},{"label":"容量限制","from":"继续收集"},{"label":"与Windows剪贴板区分","from":"它与Windows"},{"label":"重复粘贴与保存","from":"普通粘贴"}]}},"fieldPresentation":{"boundary":{"blocks":[{},{"from":"选区和键盘","role":"demo"}]},"trigger":{"blocks":[{},{"from":"网页演示","role":"demo"}]}}},{"q":10,"target":null,"chapter":3,"section":"3.2","topic":"按样式选择","title":"按同一格式或样式批量选中文本","conclusion":"要删除所有“标题1”文字，应先选中所有匹配的标题段落，再删除内容；清除格式与删除文字是两种操作。","points":["按样式选择：开始→样式，打开目标样式的菜单，选择所有使用该样式的实例，再核对选区。","按外观选择：先选中一个目标，再用开始→选择→选择格式相似的文本。相同外观可能来自不同样式，不能仅凭选中结果认定它们都属于“标题1”。","执行删除前确认选择的是全部目标文字；要调整格式时保留文字，不按Delete。"],"boundary":"不要把“删除样式”当作删除所有标题内容。","type":"单选","trigger":"从按样式选择的判断与应用整理。","id":"y2022q10","sources":[{"year":2022,"q":10,"type":"单选"}],"keys":["2022-10"],"comparison":{"headers":["做法","文字内容","格式或样式"],"rows":[["选中后按Delete","删除所选内容","不是修改样式定义"],["清除格式","保留内容","移除相应格式"],["修改“标题1”样式","保留内容","更新使用该样式的格式规则"]]},"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"按样式选中可以批量删文字；只要统一标题格式时应修改样式定义并保留内容。"},{"id":"y2025q48","label":"查找替换可批量处理文本、特殊字符与格式","reason":"查找替换也能按格式匹配，但要核对查找条件，防止相同外观掩盖不同样式。"}]},{"q":55,"chapter":3,"section":"3.2","type":"操作","topic":"校对标记","title":"校对波浪线提示可能的问题，不属于打印正文","trigger":"题目解释Word正文下方红色、绿色波浪线为何不出现在打印稿。","conclusion":"拼写、语法检查的波浪线是编辑提示，不是文档下划线，正常打印正文时不会把这些提示线印出来。","points":["红色波浪线通常提示可能的拼写问题；语法等提示颜色会随版本和校对组件变化，应根据校对建议判断，不能只背颜色。","右击标记可查看建议、忽略提示；已确认正确的专有词可加入词典。提示是待核查线索，不代表原文一定错误。","审阅→拼写和语法，或按F7启动检查；大量误报时先核对所选文字的校对语言。","自动更正会按设置把输入中的特定内容替换为预设结果，可在文件→选项→校对→自动更正选项中检查。它与“只画波浪线提示可能错误”不同；发现自动替换不合本意时撤销并核对规则，不因软件已替换就认定原文一定错。","字数统计：审阅→字数统计，或单击状态栏字数；Ctrl+Shift+G可打开统计对话框。先选中文字可查看选区统计，不选择时查看文档统计；字数、字符数（计空格/不计空格）、段落数、行数、页数不是同一个指标。需要计入文本框、脚注和尾注时核对相应选项；行数和页数会随排版改变。 例如computer是一个英文单词，却含8个字母；中文字符、非中文单词与字符数不能机械互换，混合文本按统计窗口的具体项目和范围判断。"],"boundary":"字体设置中的单下划线、双下划线属于正文格式，会打印；隐藏校对提示也不等于改正原文。","id":"y2023q55","sources":[{"year":2023,"q":55,"type":"操作"}],"keys":["2023-55"],"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"正文下划线属于字符格式会打印，校对波浪线只提示可能的问题。"},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"隐藏校对提示与隐藏修订都只影响查看；原文是否改正或修订是否处理需另外判断。"}],"pointGroups":[{"title":"提示与实际校对","indices":[0,1,2]},{"title":"自动更正与字数统计","indices":[3,4]}],"searchAliases":["自动更正","字数统计","Ctrl+Shift+G","F7","拼写","语法"],"pointPresentation":{"3":{"title":"自动更正","navigationLabel":"自动更正"},"4":{"title":"字数统计","navigationLabel":"字数统计","blocks":[{"label":"打开统计窗口"},{"label":"先确定统计范围","from":"先选中文字"},{"label":"分清统计指标","from":"字数、字符数"},{"label":"附加内容与排版条件","from":"需要计入"},{"label":"例子：单词与字符不同","from":" 例如computer"}]}}},{"q":7,"chapter":3,"section":"3.2","type":"单选","topic":"文本选择","title":"Ctrl+Shift+End选到文档末尾","trigger":"题目要求从当前插入点一次选择到Word文档末尾。","conclusion":"在Word中，Ctrl+Shift+End从当前插入点扩展选择到文档末尾；Ctrl+End只移动光标而不选择。","points":["Shift负责扩展选择，Ctrl+方向或Home/End负责跨更大范围移动。","Ctrl+Shift+Home可从当前位置选择到文档开头。","Shift+End通常只选择到当前行末。","连续选择：可左键拖过文字，或先单击起点，再按住Shift单击终点。需要不连续片段时，先选第一处，再按住Ctrl拖选后续片段；注意Ctrl在正文中单击通常用于选中一句，不能和Ctrl拖选混淆。矩形文本区域可按住Alt拖选，这也不是普通连续选区。","鼠标位置决定选择单位。在正文中双击通常选一个词，三击选一个段落，Ctrl单击选一句；在正文左侧选定栏（指针朝向正文时）单击选一行、双击选一段，三击或Ctrl单击选全文。中文分词边界可能与直觉不同，执行删除或格式命令前核对高亮范围。","Home、End通常移动到当前行首、行末；Ctrl+Home、Ctrl+End移动到文档开头、末尾。加入Shift表示从原插入点扩展选择：Shift+Home/End选到行首/行末，Ctrl+Shift+Home/End选到文首/文末。Ctrl+A选择全文；鼠标单击新位置通常取消原选区并重新定位。","定位到已知位置可按Ctrl+G或F5打开“定位”，选择页、节、行或书签等目标，输入编号后定位；这是移动插入位置，不等于选中该页全部内容。Ctrl+F偏向按文字查找和导航，Ctrl+H进入替换。"],"boundary":"Home/End的作用范围会受Ctrl和Shift组合影响，答题时要同时检查“移动到哪里”和“是否选择”。","id":"y2024q7","sources":[{"year":2024,"q":7,"type":"单选"}],"keys":["2024-7"],"related":[{"id":"y2022q10","label":"按同一格式或样式批量选中文本","reason":"连续键盘选区与按样式跨位置选区服务不同批量任务，先确认目标范围再删除或改格式。"},{"id":"syllabus-word-text-editing","label":"输入、复制与移动","reason":"先选对对象，再按完整操作链改稿。"}],"pointGroups":[{"title":"键盘选区的核心规则","indices":[0,1,2,5]},{"title":"鼠标选择与选定栏","indices":[3,4]},{"title":"按位置定位","indices":[6]}],"searchAliases":["选定栏","矩形选择","不连续文本","Ctrl+A","Shift+单击","Alt+拖动","Ctrl+G","F5","Home","End"]},{"q":9,"chapter":3,"section":"3.2","type":"单选","topic":"查找替换","title":"查找替换可批量处理文本、特殊字符与格式","trigger":"真题从删除空段、段落对齐和批量清除字符格式考查查找替换。","conclusion":"查找内容决定“找谁”，替换文字和替换格式决定“改成什么”。同样文字替换回去并指定常规字形，可以只改变匹配文字的字形。","points":["指定文字恢复常规：按Ctrl+H，在“查找内容”和“替换为”都输入目标文字；将光标放到“替换为”，再选更多→格式→字体→常规。","核对两个文本框下方的格式摘要。查找一侧残留的字体、样式等条件会缩小匹配范围；用“不限定格式”清除不需要的条件，再设置本次条件。","只替换格式时，可让查找与替换文本框留空，分别设置查找格式和目标格式；不要将“替换为空”与“留空但指定替换格式”混为一谈。","清理连续空段时，在未启用“使用通配符”的条件下，可把^p^p替换为^p。若有更多连续空段，需重复处理；若段内还有空格或制表符，则不等于连续两个段落标记。","查找替换可改变匹配内容的字符或段落格式，也可匹配样式，但不能代替在样式库中修改样式定义。嵌入型图片跟随所在段落对齐，调整图片所在段落可使其居中。 “格式”菜单还可指定制表位等条件；查找对象是具有该格式的内容，仍需检查实际命中，不能把制表位条件与查找制表符字符混同。","“常规”同时取消加粗和倾斜；题目只要求取消某一种效果时，应核对是否需要保留其他效果。先检查匹配和替换范围，再执行全部替换。","普通改词：Ctrl+H→查找内容输入旧词→替换为输入新词→先用“查找下一处”和“替换”核对一处，再决定是否“全部替换”。仅把旧词替换为空且未指定替换格式，是删除匹配文本；单击清空查找框本身不会删除正文。","按Ctrl+F打开导航窗格，可查看标题、页面缩略图和搜索结果；点击结果跳到对应内容。复杂条件用开始→查找下拉菜单→高级查找，展开“更多”；按当前选区还是全文、向上还是向下查找，应看范围与提示，避免处理完选区后又无意继续到整篇。","“区分大小写”“全字匹配”、区分全半角以及忽略空格/标点等条件会改变匹配集合。比如只想改英文单词cat，不想改到catalog，应核对全字匹配；中文词边界、文档语言和版本选项会影响结果，先检查实际命中。 高级查找还可按前缀、后缀限制词的匹配，例如只匹配以指定串开头或结尾的词；是否可同时使用其他选项应以对话框可用状态为准。","Word只有启用“使用通配符”才按相应模式匹配；?代表单个字符，*可匹配一串字符，贪多的模式可能跨过本想保留的文本。它与Windows文件名搜索、Excel通配符不能整套照搬；本节不要求把所有内容套进一个复杂表达式。","查找结构标记时，优先从“特殊格式”菜单插入代码。在未启用通配符的查找中，^p是段落标记、^l是手动换行、^t是制表符、^m是手动分页符；自动换行与自动分页不是可同样删除的手动标记。开启通配符后可用的代码与查找/替换框位置不同，不把未开通配符的^p规则直接照搬。删除结构标记可能合并段落或改变排版，先逐处核对。"],"boundary":"相同文字换回去而未设置替换格式，不保证去掉原有加粗；格式条件放错一侧，会改变查找范围或替换结果。","id":"y2025q48","sources":[{"year":2024,"q":9,"type":"单选"},{"year":2025,"q":48,"type":"操作"}],"keys":["2024-9","2025-48"],"comparison":{"headers":["目标","查找设置","替换设置"],"rows":[["改文字","输入原词","输入新词"],["删除指定文字","输入原词","留空且不指定替换格式"],["指定文字恢复常规","输入目标词","相同词＋字形常规"],["只改格式","文本留空＋原格式","文本留空＋目标格式"]]},"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"替换匹配格式不等于修改样式定义；要让以后同级标题也继承规则，应改样式。"},{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"清理连续空段前先认清段落标记与手动换行，避免替换错结构。"},{"id":"y2024q57","label":"用-*通配符批量删除连字符及其后缀","reason":"Excel和Word的通配符入口及语法不同，跨软件操作不能照搬勾选步骤。"}],"pointGroups":[{"title":"先完成普通查找与替换","indices":[6,7,8]},{"title":"按字形或格式批量处理","indices":[0,1,2,5,4]},{"title":"识别特殊标记与通配条件","indices":[3,9,10]}],"searchAliases":["查找下一处","全字匹配","区分大小写","使用通配符","^p","^l","^t","^m","删除空段"]},{"q":4,"chapter":3,"section":"3.3","type":"单选","topic":"多级列表","title":"项目符号、编号与多级列表","trigger":"四道题从入口、层级调整和缩进排错考查Word列表功能。","conclusion":"项目符号适合无序内容，编号适合有序内容；多级列表用编号位置、文本缩进和制表位共同控制层级版式。","points":["项目符号、编号和多级列表位于开始→段落。无先后关系用项目符号；顺序步骤用编号；章节层次用多级列表。","在列表项文本开头，Tab通常降一级、Shift+Tab通常升一级；行为还受自动调整缩进设置影响。也可在多级列表菜单中使用“更改列表级别”。","一级“1.”与二级“1.1”要建立真正层级。章节编号可先应用“标题1”“标题2”，再从多级列表库选择带标题样式的编号方案；只增大左缩进或只改编号字体，都不会替代标题层级。","编号错位时分别检查编号对齐位置、文本缩进位置和编号后的制表位；不要用连续空格手工补齐。","自定义项目符号可使用符号或图片；符号可设置字体、颜色。编号可设置样式和起始值，不必逐项手改数字。 编号也可在定义新编号格式中设置字体及颜色；不能把可自定义图片项目符号理解为自动编号数字也可直接用图片替换。","列表作用于段落：选中各项段落后应用项目符号或编号；在列表项末尾按Enter通常延续下一项，在空列表项再次Enter通常结束列表。Shift+Enter仅在同一项内换行。手动输入“1.”或用插入→符号插入编号字符，不能保证建立自动编号；是否自动转为列表还取决于自动更正设置。","编号与文字间空隙过大时，先分清编号起点和正文起点。题设编号位置正确而正文过远，应减小该级的文本缩进；若“编号之后”选择制表符，还需使制表位与预期文字起点协调。改成空格或无时空隙机制不同，不能断言只改编号位置永远不影响间距，也不能只靠改变字体解决缩进问题。"],"boundary":"不要用空格手工对齐多级编号；普通正文中的Tab可能只是插入制表符。","version":"已转换为Word 2016","id":"merged-8","sources":[{"year":2020,"q":4,"type":"单选"},{"year":2026,"q":56,"type":"分析"},{"year":2026,"q":57,"type":"分析"},{"year":2026,"q":58,"type":"分析"}],"keys":["2020-4","2026-56","2026-57","2026-58"],"related":[{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"编号错位常要调整文本缩进和制表位，先认清首行、悬挂与整段缩进。"},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"章节多级编号应与标题层级协调，单纯增大缩进不会建立可导航的标题结构。"}],"pointGroups":[{"title":"选择列表类型与段落范围","indices":[0,5]},{"title":"建立和调整真实级别","indices":[1,2]},{"title":"编号、文本与符号的区别","indices":[3,6,4]}]},{"q":41,"chapter":3,"section":"3.3","type":"操作","topic":"分节页眉","title":"页眉由节、链接状态与首页/奇偶页选项共同决定","trigger":"真题从同节页眉差异、普通页眉输入和长文档分节页眉考查真实规则。","conclusion":"先用分节确定不同内容的范围，再分别管理页眉和页脚的链接；首页不同、奇偶页不同会增加独立的页眉页脚类型。","points":["进入编辑：在打印布局中双击页面顶部，或用插入→页眉→编辑页眉。输入内容前确认当前页属于哪一节、哪一种页眉。","新节默认可能沿用前一节。看到“与上一节相同”时，先取消“链接到前一节”，再修改新节内容，否则可能同时改到前节。","页眉与页脚分别链接；首页页眉、奇数页页眉、偶数页页眉也各自链接到前一节的相同类型。只断开一种，不会自动断开其余类型。","封面、目录均无页眉，而正文单独设置：在正文前插入“下一页”分节符，再断开正文相应页眉链接。若正文页码位于页脚，还要单独检查页脚链接。","正文从1编号：在正文节插入页码，打开“设置页码格式”，选择起始页码1。取消链接改变的是页眉页脚内容的继承；起始页码决定编号。"],"boundary":"“首页不同”处理的是一节的首页，不能单独让封面和目录两页都无页眉；分页符换页但不建立新的节。","version":"已转换为Word 2016","id":"y2020q41","sources":[{"year":2020,"q":41,"type":"操作"},{"year":2023,"q":9,"type":"单选"},{"year":2024,"q":56,"type":"操作"},{"year":2021,"q":44,"type":"操作","page":7}],"keys":["2020-41","2023-9","2024-56","2021-44"],"comparison":{"headers":["设置","控制什么","不能代替什么"],"rows":[["分节符","划分独立设置范围","不会自动取消前节链接"],["链接到前一节","当前类型沿用前节内容","不会自动改起始页码"],["首页不同","本节首页单独一套内容","不能处理任意多页前置内容"],["奇偶页不同","奇数页、偶数页分开","不能自动按章节填写不同文字"]]},"related":[{"id":"y2020q61","label":"只改变一页纸张方向","reason":"不同页眉的范围由节划定；分页符只换页，不能建立独立页眉设置范围。"},{"id":"y2024q55","label":"在形状中放置光标后插入PAGE域","reason":"页码用PAGE域保持动态，但在哪一节显示及如何起号还要检查链接与编号设置。"},{"id":"y2024q54","label":"页眉横线应作为段落下边框设置","reason":"页眉横线通常是段落边框，删页眉文字后仍有横线时应检查它。"}],"pointGroups":[{"title":"确认页眉类型并管理节间链接","indices":[0,1,2]},{"title":"正文独立页眉与从1起号","indices":[3,4]}]},{"q":42,"chapter":3,"section":"3.3","type":"操作","topic":"字符与段落格式","title":"显示、字符格式与段落对齐要分清","trigger":"真题从字号、上标、字形、下划线、显示缩放和段落对齐反复考查格式边界。","conclusion":"先判断改变的对象：字符格式管字，段落格式管整段排布，显示比例管屏幕查看。三者都可能让文字“看起来变了”，但对打印的影响不同。","points":["上标抬高并缩小所选字符，下标降低并缩小所选字符。Word快捷键：上标Ctrl+Shift+=，下标Ctrl+=；它们改变格式，不是把内容改成另一种Unicode字符。","字体对话框可设置字形、字号、单/双下划线、删除线和着重号；校对波浪线只是提示，不属于这些打印格式。","字体颜色改变字本身；文本突出显示颜色像荧光笔标记字符背景；段落底纹按段落范围着色，页面颜色改变页面背景。","两端对齐通常不拉伸自然结束的末行；分散对齐可让末行也分散到左右边界。判断时检查最后一行，并区分自然段结束与手动换行。","标题要求居中且无首行或悬挂偏移：设置段落居中，并把特殊格式设为“无”；若已有左右缩进，还需核对它们是否符合要求。","全角１２３与半角123是不同字符。选中文字后可在中文Word的开始→字体→更改大小写→半角中转换；格式刷只复制格式，不做这种字符转换。","设置字符格式前，先选中要处理的文字；未选择时设置字体通常影响插入点后新输入的内容，不能当成已修改全文。入口是开始→字体，更多项目用字体组对话框启动器或Ctrl+D；选中文字后也可使用浮动工具栏。","字号常以磅（pt）表示，1磅为1/72英寸，磅值越大通常字越大。中文字号名称中，五号比小五大，四号比五号大；“号”的数字不能按磅值的大小方向去比较。字体不同，同字号字面观感仍可不同。屏幕显示缩放不改实际字号，打印题应检查字体设置。","加粗Ctrl+B、倾斜Ctrl+I、下划线Ctrl+U可分别切换；下划线在文字下方，删除线穿过文字，着重号是强调标记，不是校对波浪线。需要双下划线、特定颜色或字形“常规”时进入字体对话框，不把同时清除粗体和斜体当成只取消一种效果。","字符间距在字体对话框→高级中设置。“间距”的加宽/紧缩改变字符之间的距离；“缩放”按比例拉宽或压窄字符；“位置”的提升/降低改变相对基线的位置。三者与字号、行距以及中文与数字自动间距不同，不能把“加宽”解释成缩小间距。","复制格式：选取有目标格式的文字→开始→剪贴板→格式刷→刷过目标文字。单击格式刷通常使用一次，双击可连续刷多处，Esc退出。若同时要复制段落格式，源选区应包含段落标记；只选几个字不能保证取得整段设置。格式刷复制格式，不复制文字内容或把半角数字转换成全角。","清除格式：选中目标→开始→字体→清除所有格式，文字内容仍保留；要精确取消一项，直接取消对应按钮更合适。直接格式会与样式叠加，不能把清除格式当作删除文字或修改样式定义。","段落对齐先确定作用段落，再用开始→段落选择左对齐、居中、右对齐、两端对齐或分散对齐；常用快捷键为Ctrl+L/E/R/J，分散对齐为Ctrl+Shift+J。对齐在段落的左右缩进边界之间计算；“默认两端对齐/默认单倍行距”取决于模板、样式和已改设置，不能当成每份Word2016文档都必然如此。","普通文字的边框和底纹也要确认范围：选中文字→开始→段落→边框下拉→边框和底纹，核对“应用于”文字还是段落；底纹页设置填充。文字边框/底纹围绕相应文字区域，段落边框/底纹按整段区域处理。字体颜色、突出显示、文字底纹和页面背景并非同一个设置，清除其中一种不保证其他颜色也消失。"],"boundary":"要求“打印时字更大”应改字号，要求“屏幕上看得更大”可改缩放；先确认目标，不能用同一个按钮替代。","id":"merged-7","sources":[{"year":2020,"q":42,"type":"操作"},{"year":2023,"q":51,"type":"操作"},{"year":2024,"q":52,"type":"操作"},{"year":2025,"q":29,"type":"多选"},{"year":2025,"q":46,"type":"操作"},{"year":2026,"q":46,"type":"操作"},{"year":2022,"q":53,"type":"操作"},{"year":2021,"q":42,"type":"操作","page":6},{"year":2021,"q":43,"type":"操作","page":6}],"keys":["2020-42","2023-51","2024-52","2025-29","2025-46","2026-46","2022-53","2021-42","2021-43"],"comparison":{"headers":["层级","典型项目","影响打印"],"rows":[["字符格式","字体、字号、字形、上下标、下划线","会改变字的排版或外观"],["段落格式","对齐、缩进、段前段后、行距","会改变段落排布"],["显示比例","100%改为150%","不改变文档打印尺寸"]]},"related":[{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"段落末行的对齐效果取决于段落结构，Enter与手动换行不能混用。"},{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"居中后仍有偏移时，应继续检查首行、悬挂和左右缩进标记。"},{"id":"y2025q2","label":"字符编码、汉字机内码、字形与全角半角要分清","reason":"全角半角转换改变字符身份，不能把它当成只改变字号或字体的操作。"}],"pointGroups":[{"title":"选定对象、字体与字号","indices":[6,7,0,1]},{"title":"字形、颜色和字符间距","indices":[8,2,9,13]},{"title":"复制或清除格式","indices":[10,11,5]},{"title":"段落对齐与末行判断","indices":[12,3,4]}],"searchAliases":["字体","字号","磅","格式刷","Ctrl+D","字符缩放","加宽","紧缩","删除线","着重号","清除格式","分散对齐"]},{"q":43,"chapter":3,"section":"3.3","type":"操作","topic":"段落缩进与换行","title":"首行缩进属于段落，手动换行不会新建段落","trigger":"真题从手工空格和手动换行符考查首行缩进的作用范围。","conclusion":"首行缩进作用于每个段落的第一行。Enter建立新段落，Shift+Enter只在原段落内换行，自动换行也不会重算一个新段落的首行。","points":["设置2字符首行缩进：选中正文段落→开始→段落对话框→缩进和间距→特殊格式“首行缩进”→度量值“2字符”。","在开始→段落中开启“显示/隐藏编辑标记”：段落标记是¶，手动换行标记是弯箭头。以标记判断结构，不能只看视觉上是否另起一行。","首行缩进只改变第一行；左缩进改变整段的左侧位置；悬挂缩进使首行之外的各行相对缩进。","不要靠段首空格凑2字符。空格属于内容，会受字体与字号影响，也不能给每个新段落建立稳定的缩进规则。","要让后文从下一页开始，可用Ctrl+Enter插入手动分页符；它与Enter新段落、Shift+Enter同段换行、分节符建立新节不同。不应连续敲Enter凑出下一页，因为前文变化后这些空段会重新占位置。","段落对话框→换行和分页中：“孤行控制”用于避免段首或段尾单独一行留在页边；“与下段同页”尽量让本段与下一段的开头同页，常用于标题；“段中不分页”尽量让本段各行同页；“段前分页”使本段从新页开始。这些控制分页，不负责把三行文字横向挤成两行；连续设置涉及的内容超过一页时仍需分页，超长段落与版面约束应检查实际结果。"],"boundary":"下一行是否执行首行缩进，取决于它是否属于新段落；按Enter后的新段还受“后续段落样式”等样式规则影响。","id":"y2020q43","sources":[{"year":2020,"q":43,"type":"操作"},{"year":2024,"q":51,"type":"操作"}],"keys":["2020-43","2024-51"],"comparison":{"headers":["换行方式","是否新段落","首行缩进"],"rows":[["文字到行末自动换行","否","仍按原段落的非首行排布"],["Shift+Enter","否","不会因换行重新成为首行"],["Enter","是","按新段落的格式规则执行"]]},"related":[{"id":"y2022q24","label":"标尺四个缩进标记控制不同的行","reason":"首行、悬挂和整段左缩进可用标尺分别调节，先按受影响的行确定标记。"},{"id":"y2025q48","label":"查找替换可批量处理文本、特殊字符与格式","reason":"替换空段要识别真正的段落标记；手动换行与含空格的空行不等于连续空段。"}],"workedExamples":[{"year":2020,"q":43,"questionSummary":"只让每个正文段落第一行缩进两个字符。","reasoning":["目标只改变每段第一行，相应属性是首行缩进。","左缩进会移动整段，悬挂缩进主要移动除第一行外的后续行。","逐段敲空格只是字符内容，不是稳定的段落格式。"],"pitfall":"把“从左边空两格”误解为整段左缩进，或用空格模拟排版。","transfer":"先选中需要设置的段落，再设置特殊格式首行；按Enter形成新段落，手动换行仍在原段落内。","sourceURL":"https://www.sohu.com/a/422753629_100179611","sourceStatus":"本轮已核对原卷PDF第6页第43题及第5页图3；配套参考答案无可确认的官方发布依据。公开链接为转录入口。","historicalVersionNote":"该年公开题面沿用Windows 7/Office 2010。此处保留原题语境；站内操作入口须按Windows 10/Office 2016另行说明。"}],"pointGroups":[{"title":"首行缩进与段落结构","indices":[0,1,2,3]},{"title":"另起页与段落分页控制","indices":[4,5]}]},{"q":44,"chapter":3,"section":"3.3","type":"操作","topic":"分栏与页面查看","title":"正文分栏会改变排版，页面并排只改变屏幕查看","trigger":"真题从两栏排版和多页并排阅读考查两个容易混淆的功能。","conclusion":"选中文本后用“布局→栏→两栏”建立报刊式文本流；多页/并排查看只改变屏幕显示，不改变打印版式。","points":["只给一段正文分栏：先选中目标文字，再用布局→栏→两栏；“更多栏”中核对“应用于”范围。Word可用连续分节符隔离所选部分。","文字通常按左栏从上向下，再流向右栏；要提前转到下一栏可插入分栏符，不必用大量空行顶过去。","更多栏可设置栏数、栏宽、间距和分隔线；不等栏宽需要取消等宽设置后分别调整。","分栏会改变正文排版和打印结果；视图中的多页显示、并排查看只改变屏幕查看方式。"],"boundary":"插入表格模拟两栏不等于真正分栏；页面并排也不会把正文自动变成两栏。","version":"已转换为Word 2016","id":"y2020q44","sources":[{"year":2020,"q":44,"type":"操作"},{"year":2023,"q":53,"type":"操作"}],"keys":["2020-44","2023-53"],"related":[{"id":"y2020q61","label":"只改变一页纸张方向","reason":"局部分栏与局部横向都要核对应用范围及分节边界，避免版式影响后文。"},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"Web版式、多页查看等属于视图选择，不能代替会影响打印的正文分栏。"}]},{"q":61,"chapter":3,"section":"3.3","type":"综合","topic":"分节","title":"只改变一页纸张方向","trigger":"题目要求让表格所在页横向，而前后页面仍为纵向。","conclusion":"纸张方向按节设置。只让中间一页横向，要把该页内容单独分成一节，并确认横向仅应用于这一节。","points":["手动分节：在目标页内容前插入布局→分隔符→下一页分节符；在目标内容后再插入下一页分节符，使后文重新成为另一节。","把光标放在目标节，打开页面设置，设为横向并确认“应用于：本节”；再检查前后两节仍为纵向。","也可先选择需要横向的内容，在页面设置中选横向，并把“应用于”设为“所选文字”；Word会为不同方向建立所需分节边界。","节还可分别控制页边距、页眉页脚和页码设置；但页眉页脚是否沿用前节，要另外看链接状态。"],"boundary":"如果只在目标页之前分节而没有隔离后文，横向可能继续影响后面的多页；操作后必须检查相邻页。","id":"y2020q61","sources":[{"year":2020,"q":61,"type":"综合"}],"keys":["2020-61"],"comparison":{"headers":["分隔方式","作用","能否单独隔离纸张方向"],"rows":[["分页符","从新页继续同一节","不能"],["下一页分节符","从新页开始新节","可以划出节边界"],["连续分节符","在当前页开始新节","常用于同页分栏等设置"]]},"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"分节能隔离纸张方向，但页眉页脚是否继承还需单独检查链接状态。"},{"id":"y2020q44","label":"正文分栏会改变排版，页面并排只改变屏幕查看","reason":"局部分栏可使用连续分节，局部横向常用下一页分节；二者都需核对影响范围。"},{"id":"y2025q10","label":"PowerPoint的节用于组织，导航最终定位幻灯片","reason":"Word的节可控制页面方向，PowerPoint的节主要组织幻灯片，不能套用相同能力。"}]},{"q":56,"target":null,"page":9,"chapter":3,"section":"3.3","topic":"模板与样式","title":"样式统一一份文档，模板给多份文档共同起点","conclusion":"把标题、正文等格式定义为样式，再保存为模板，让不同文档从同一套规范开始。","points":["先明确标题、正文的字体、字号、段落间距和缩进，再分别建立样式；修改样式可更新使用它的内容，但已有直接格式可能仍覆盖某些属性，要检查例外。","把样式、页面设置和固定内容保存为模板；不含宏常用.dotx，含宏用.dotm，普通文档常用.docx。","从模板新建的是独立文档。修改新文档正文不会默认写回模板，修改模板也不会默认更新已经创建的所有旧文档。","实施顺序：建立样式→保存模板→基于模板新建文档→应用对应样式→检查局部例外。"],"boundary":"保存模板不意味着所有旧文档自动更新；仍需新建时选模板或把相应样式应用到旧文档。","type":"分析","trigger":"围绕模板与样式的识别、应用与易错边界整理。","id":"y2021q56","sources":[{"year":2021,"q":56,"type":"分析"},{"year":2021,"q":57,"type":"分析","page":10}],"keys":["2021-56","2021-57"],"comparison":{"headers":["工具","适合什么","维护方式"],"rows":[["直接格式","某个词、某段的局部例外","只改选中内容"],["格式刷","把已有格式复制到少量目标","源格式以后改变，目标不自动跟随"],["样式","一份文档中同类内容统一","修改样式规则"],["模板","多份新文档共用起点","基于模板创建独立文档"]]},"related":[{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"先在单份文档建立可统一修改的样式，再把样式保存进模板供新文档使用。"},{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"把标题样式写入模板，既统一外观，也为导航、自动目录提供结构。"}],"pointGroups":[{"title":"先建立可统一修改的样式","indices":[0]},{"title":"保存模板并为新文档选用","indices":[1,2,3]}]},{"q":24,"target":null,"chapter":3,"section":"3.3","topic":"标尺与缩进","title":"标尺四个缩进标记控制不同的行","conclusion":"拖标尺前先确定要移动第一行、其余行、整段左边界还是右边界。左下方方块会带着首行和悬挂标记一起移动，保留它们的相对距离。","points":["先选中需要调整的段落，在视图中显示标尺，再拖相应标记；否则可能只修改光标所在段落。","首行比其余行更靠右表现为首行缩进；首行比其余行更靠左表现为悬挂缩进。不要把三角形朝向直接当作“向左/向右缩进”。","拖页边距交界改变页面可排版区域；拖缩进标记改变段落相对该区域的位置。行距、段前和段后间距不由水平标尺这些标记控制。","需要准确数值时，选中段落→开始→段落对话框→缩进和间距，分别设置左、右缩进及特殊格式。先看页边距，再看段落缩进；缩进通常以正文可排版区域为参照，不是从纸张物理边缘量起。","例如左页边距3厘米、段落左缩进1厘米且无首行/悬挂时，各行起点距纸张左边缘4厘米；若再设首行缩进0.5厘米，第一行起点为4.5厘米，其余行仍为4厘米。悬挂缩进应分别检查第一行和后续行，不能只看最靠左的一行就断言左缩进为0。"],"boundary":"先分清“第一行”“其余行”“整段”，不要把首行缩进和悬挂缩进方向记反。","type":"多选","trigger":"从标尺与缩进的判断与应用整理。","id":"y2022q24","sources":[{"year":2022,"q":24,"type":"多选"}],"keys":["2022-24"],"comparison":{"headers":["标记","拖动后改变","其余部分"],"rows":[["左上三角","第一行的起点","其余行起点保留"],["左下三角","除首行外各行的起点","首行起点保留"],["左下方块","整个段落的左侧位置","首行与其余行的差值保留"],["右端三角","段落右边界","不等于页面右页边距"]]},"related":[{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"观察第一行和其余行的位置，才能区分首行缩进与悬挂缩进。"},{"id":"merged-8","label":"项目符号、编号与多级列表","reason":"多级列表的编号位置、文本缩进与制表位要协调，不能只拖一个标记或堆空格。"}],"pointGroups":[{"title":"标尺对应哪部分","indices":[0,1,2]},{"title":"精确设置与距离判断","indices":[3,4]}]},{"q":70,"target":null,"chapter":3,"section":"3.3","topic":"页面背景","title":"图片水印、页面背景和衬于文字下方各有入口","conclusion":"Logo放在正文后方，可用图片水印、页面颜色的图片填充，或普通图片设为衬于文字下方。","points":["图片水印适合重复出现的淡化标识：设计→水印→自定义水印→图片水印，选择Logo并设置缩放、冲蚀等选项。需要选择或移动已有水印时，先进入页眉编辑。","普通图片需设置环绕、大小和位置，不会天然推广到每页。","页面背景图片走设计→页面颜色→填充效果→图片；若编辑画面可见而打印稿没有背景，检查文件→选项→显示→打印选项→打印背景色和图像，再查看打印预览。"],"boundary":"页面边框控制边缘线条，不负责把Logo作为整页背景；背景也不应遮挡正文。","type":"综合","trigger":"从页面背景的判断与应用整理。","id":"y2022q70","sources":[{"year":2022,"q":70,"type":"综合"}],"keys":["2022-70"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"普通背景图片需要设置文字环绕和锚定关系；衬于文字下方不会天然重复到每页。"}],"pointGroups":null},{"q":52,"chapter":3,"section":"3.3","type":"操作","topic":"样式","title":"统一修改同级标题应直接修改样式","trigger":"题目要求让所有“标题1”段落统一增加段前20磅。","conclusion":"在样式库中右击“标题1→修改→格式→段落”，把段前设为20磅，可一次更新所有使用该样式的标题。","points":["先检查目标段落确实使用“标题1”；仅手动加粗、放大成相同外观的段落不会因此受到样式修改。","开始→样式，右击标题1→修改→格式→段落，把段前设为20磅，确认后核对所有同级标题。","样式可同时包含字符与段落格式，后续应用同一样式的标题也会继承该规则；若某段仍不同，检查是否存在覆盖样式的直接格式。","需要把新规则用于以后基于模板创建的文档时，再明确设置模板保存范围；修改当前文档不等于改了所有旧文件。"],"boundary":"格式刷适合少量复制，不是全局规则；修改某一段的直接格式也不会自动更新所有同级标题。","id":"y2023q52","sources":[{"year":2023,"q":52,"type":"操作"}],"keys":["2023-52"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"只有真正使用标题样式或大纲级别的段落才形成可靠导航和目录结构。"},{"id":"y2021q56","label":"样式统一一份文档，模板给多份文档共同起点","reason":"当前文档样式规则确定后，可保存进模板；修改当前文档不自动更新所有旧文件。"},{"id":"y2022q10","label":"按同一格式或样式批量选中文本","reason":"想删所有某样式文字时要选中实例，修改或删除样式定义不是删除这些内容。"}]},{"q":54,"chapter":3,"section":"3.3","type":"操作","topic":"页眉边框","title":"页眉横线应作为段落下边框设置","trigger":"题目要求改变页眉自动横线的颜色和宽度。","conclusion":"把光标放入页眉段落，打开“边框和底纹→边框”，设置线型、颜色和宽度，并把下边框应用于段落。","points":["横线通常是页眉段落的下边框，不是可拖动的普通直线形状。","“应用于：段落”决定边框随页眉段落宽度延伸。","预览区只保留下边框可避免四周都出现线。","删除页眉文字后横线仍在时，应检查页眉段落下边框；选中页眉段落，用“开始→边框→无框线”移除，不要反复按Delete找不存在的图片。","也可把“页眉”样式的段落边框改为无；使用该样式且未被直接格式覆盖的页眉段落会随之更新。"],"boundary":"修改页面边框会影响整页四周，修改下划线只作用于文字，两者都不能替代页眉段落边框。","id":"y2024q54","sources":[{"year":2024,"q":54,"type":"操作"},{"year":2022,"q":51,"type":"操作"}],"keys":["2024-54","2022-51"],"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"先进入正确节和正确类型的页眉，再设边框，避免因链接状态影响其他节。"},{"id":"y2023q52","label":"统一修改同级标题应直接修改样式","reason":"页眉横线也可通过页眉样式统一修改，直接格式可能覆盖样式规则。"},{"id":"y2020q60","label":"给表格设置全部框线","reason":"边框都需核对应用对象：页眉段落与整张表格的范围不同。"}],"pointGroups":[{"title":"把横线设为页眉段落下边框","indices":[0,1,2]},{"title":"删除残留横线或统一修改样式","indices":[3,4]}]},{"id":"syllabus-word-paragraph-spacing","chapter":3,"section":"3.3","origin":"syllabus","type":"知识补充","topic":"段落间距与行距","title":"段前段后与行距：分清段间和段内距离","conclusion":"段前、段后控制段落外的留白，行距控制同一段内各行的排布。固定值限制行高，最小值允许内容需要时增高。","points":["只处理一个段落时，将插入点放在该段内即可设置段落格式；处理多个段落应选中涉及的段落，处理正文全部段落先核对是否要Ctrl+A。用开始→段落对话框→缩进和间距，或布局中的段前/段后输入框设置；字符选区很短，也可能改变它所在整段的段落格式。","段前在段落前增加留白，段后在段落后增加留白；它们不是空格，也不增加空段。按题目单位输入，例如段后6磅或段前0.5行，不把“6磅”写成“6行”。相邻段落的实际留白还受间距合并、同样式段落不添加间距和页首位置等规则影响，不能只把两个框的数字相加当成实测结果。","单倍行距根据当前字体与内容安排行高；1.5倍、2倍和多倍按单倍基准调整。“1.5倍行距”不等于固定18磅，也不是增加1.5行空段。相同字体和内容下增大行距主要拉开纵向距离，不负责压缩每行的字符。","“最小值”设置行高下限，较大字体或嵌入型图片需要更多空间时允许增高；“固定值”使用指定磅值，过小可能裁切大字、公式或嵌入型图片。固定值越小不代表内容越完整，也不要把问题误判成图片文件损坏。","例如题目要求正文1.5倍行距、段后6磅：先选正文各段→段落对话框→行距选1.5倍→段后输入6磅→确定，再核对段内各行和两个段落之间的变化。标题不在任务范围时应排除标题；改行距不能代替设置段后。","如果设置看似没有生效，先核对选区、单位、所选行距类型，再看“如果定义了文档网格，则对齐到网格”等选项、样式和内容对象。默认格式来自模板与样式，不能把课堂示例的初始值当成所有文档统一默认值。"],"boundary":"行距、字号、字符间距、段前段后和页面留白属于不同参数。要把文字多占一行的原因找准，仍须同时检查行宽、字体及横向间距。","sources":[],"keys":[],"searchAliases":["段前","段后","段落间距","单倍行距","1.5倍行距","多倍行距","固定值","最小值","文档网格"],"trigger":"按2026年考试要求与已核查课堂范围补充；操作以Windows桌面Word2016为基线，具体来源见参考资料。网页演示不等于真实Word实测。","pointGroups":[{"title":"作用范围和段落外留白","indices":[0,1]},{"title":"段内行距的类型与限制","indices":[2,3]},{"title":"按要求设置并排错","indices":[4,5]}],"related":[{"id":"y2024q66","label":"固定行距裁切图片","reason":"用嵌入型对象核对固定值与最小值的边界。"},{"id":"y2020q43","label":"换行与分页控制","reason":"区分行距、段落结构与分页设置。"}],"pointPresentation":{"0":{"title":"设置对象与入口","navigationLabel":"设置对象与入口","blocks":[{"label":"处理哪些段落"},{"label":"操作入口","from":"用开始"},{"label":"作用范围提醒","from":"字符选区"}]},"1":{"title":"段前与段后","navigationLabel":"段前与段后","blocks":[{"label":"控制段落外留白"},{"label":"核对输入单位","from":"按题目单位"},{"label":"相邻段落的条件","from":"相邻段落"}]},"2":{"title":"单倍与倍数行距","navigationLabel":"倍数行距"},"3":{"title":"最小值与固定值","navigationLabel":"最小值与固定值","blocks":[{"label":"最小值"},{"label":"固定值","from":"“固定值”"},{"label":"裁切问题","from":"固定值越小"}]},"4":{"title":"设置1.5倍行距、段后6磅","navigationLabel":"设置步骤与核对","blocks":[{"label":"题目要求"},{"label":"设置步骤","from":"先选正文","steps":["先选正文","段落对话框","行距选","段后输入","确定"]},{"label":"核对结果","from":"再核对"},{"label":"范围与易错","from":"标题不在"}]},"5":{"title":"设置未生效时的检查","navigationLabel":"设置没有生效","blocks":[{"label":"依次排查"},{"label":"默认值的来源","from":"默认格式"}]}},"fieldPresentation":{"trigger":{"blocks":[{},{"from":"网页演示","role":"demo"}]}}},{"q":66,"chapter":3,"section":"3.3","type":"分析","topic":"行距与图片","title":"固定行距过小会裁切嵌入型图片","trigger":"题目描述按Enter后粘贴图片，图片为嵌入型却只能显示一部分。","conclusion":"嵌入型图片占据文本行；若段落设置了小于图片高度的固定值行距，行框会裁切图片。","points":["改为单倍、多倍或“最小值”行距可让行高随对象增大。","若必须用固定值，应把磅值调到足以容纳图片。","图片环绕方式不是唯一原因，应先检查段落行距。"],"boundary":"“固定值”与“最小值”不同：固定值锁死行高，最小值允许内容更高时自动扩展。","id":"y2024q66","sources":[{"year":2024,"q":66,"type":"分析"}],"keys":["2024-66"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"嵌入型图片按文本行排布，因此可能被固定行高裁切；浮动图片采用另一套位置规则。"},{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"图像被裁切不一定要缩小原图，应先分辨是行距限制还是主动裁剪。"},{"id":"syllabus-word-paragraph-spacing","label":"段前段后与行距","reason":"先辨认参数再修复行高。"}]},{"q":47,"chapter":3,"section":"3.3","type":"操作","topic":"中文版式","title":"中文与数字、中文与西文的自动间距分别控制","trigger":"题目要求解释相同文字为何多占一行并选择压缩方法。","conclusion":"中文与数字、中文与西文是两个独立选项。文段含“10亿年”等数字时，应检查“自动调整中文与数字的间距”。","points":["入口：开始→段落对话框启动器→中文版式→字符间距。","取消中文与数字间距，影响汉字和数字交界处；中文与西文选项影响汉字与拉丁字母交界处。","自动间距不同于手动输入的空格；关闭自动间距不会删除真实空格，也不会改字号。","行数是否减少还取决于字体、字号和行宽，不能保证每个文段都恰好从三行变两行。","1.5倍行距主要改变行与行的纵向距离；孤行控制调整跨页时单行的分布。它们都不直接缩小汉字与数字的横向间距，不能用“行距一变，原文行数一定只会增多或一定会减少”解释题目。是否换行仍要结合字符宽度和可用行宽。"],"boundary":"为挤进行数而任意缩放字符会损害可读性，应先查明真正的版式来源。","id":"y2026q47","sources":[{"year":2026,"q":47,"type":"操作"}],"keys":["2026-47"],"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"自动字符间距、字形字号与段落对齐作用不同，调整版面前应先确认要改变哪一层。"},{"id":"y2020q43","label":"首行缩进属于段落，手动换行不会新建段落","reason":"真实空格属于文本内容，缩进和自动间距属于排版规则，不能用删除空格替代所有调整。"},{"id":"syllabus-word-paragraph-spacing","label":"纵向距离不等于横向字符间距","reason":"行距与段间距各有作用范围。"}],"pointGroups":[{"title":"独立控制两类自动间距","indices":[0,1,2]},{"title":"行数变化的条件与排错","indices":[3,4]}]},{"q":60,"chapter":3,"section":"3.4","type":"综合","topic":"表格边框","title":"给表格设置全部框线","trigger":"题目比较绘制表格、边框菜单和表格属性等设置全部框线的方法。","conclusion":"选中表格后使用“开始”或“表格工具-设计”中的边框菜单设置“所有框线”最直接。","points":["边框可作用于单元格、所选区域或整张表格。","表格属性中的“边框和底纹”可精确设置线型、颜色、宽度和应用范围。","绘制表格适合补画局部线条，不适合为已有大表逐条重画。","屏幕上的表格网格线只是帮助识别单元格，不会打印。要求打印出全部线条时必须设置实际边框；可到打印预览核对，不能仅凭编辑画面中的虚线判断完成。"],"boundary":"边框快捷菜单按当前选区应用；也可把光标置于任意单元格，经表格属性→边框和底纹，把“应用于”设为“表格”。光标位于表格内即可显示表格工具，不要求先选中整表。","version":"已转换为Word 2016","id":"y2020q60","sources":[{"year":2020,"q":60,"type":"综合"}],"keys":["2020-60"],"related":[{"id":"y2020q63","label":"整张表格居中与单元格内容居中","reason":"设置前先确定选中的是表格对象还是格内文字；整表边框和格内对齐作用范围不同。"},{"id":"y2024q54","label":"页眉横线应作为段落下边框设置","reason":"边框设置都要核对“应用于”，页眉段落下边框不能用页面或表格边框替代。"}],"pointGroups":null},{"q":62,"chapter":3,"section":"3.4","type":"综合","topic":"跨页表格","title":"跨页表格重复标题行","trigger":"题目要求表格跨多页时每页顶部都显示标题行。","conclusion":"让跨页表格自动重复表头，应选中从第一行开始的连续标题行，再用表格工具→布局→重复标题行。","points":["重复行必须包含表格第一行；多行表头应连续选中，不能只选表格中部某一行作为重复表头。","也可打开表格属性→行，勾选“在各页顶端以标题行形式重复出现”。","该效果在打印布局和打印结果中查看；后续页的重复标题由首段表头生成，应修改第一页的原始标题行。","表格因内容自然跨页时会重复标题；在表格内部手动插入分页符不会得到同样的自动重复效果。"],"boundary":"“表格样式选项→标题行”主要影响样式外观，不等于跨页重复标题；页面页眉也不是表格表头。","version":"已转换为Word 2016","id":"y2020q62","sources":[{"year":2020,"q":62,"type":"综合"}],"keys":["2020-62"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"重复标题行应在打印布局核对，屏幕查看方式会影响是否看得到分页效果。"},{"id":"y2024q58","label":"选中第3行后冻结可保持前两行可见","reason":"Word重复表头用于跨页打印；Excel冻结窗格只用于滚动查看，两者用途容易混淆。"}]},{"q":63,"chapter":3,"section":"3.4","type":"综合","topic":"表格对齐","title":"整张表格居中与单元格内容居中","trigger":"题目比较段落居中、表格属性和表格工具中的水平居中。","conclusion":"整表在页面中居中，应设置表格对齐方式；单元格水平居中只改变格内内容。","points":["整表居中：右击表格→表格属性→表格→对齐方式“居中”。它改变表格对象相对排版区域的位置。","格内文字水平居中：选择目标单元格内容，使用开始→段落→居中；文字在各自单元格内移动，表格宽度与位置不因此改变。","格内水平与垂直位置一起设置：使用表格工具→布局→对齐方式的九种对齐选项；表格属性→单元格也可设置垂直对齐。","确认结果时观察表格左右留白和文字在单元格中的位置，分别判断两个目标是否达到。"],"boundary":"先分清“表格这个对象居中”还是“单元格里的文字居中”，两者按钮和结果不同。","version":"已转换为Word 2016","id":"y2020q63","sources":[{"year":2020,"q":63,"type":"综合"}],"keys":["2020-63"],"comparison":{"headers":["要求","规范入口","观察结果"],"rows":[["整张表格居中","表格属性→表格→居中","表格左右留白对称"],["格内文字水平居中","所选内容→段落居中","字在单元格内左右居中"],["格内文字上下居中","表格工具→布局→对齐方式","字在单元格内垂直居中"]]},"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"开始选项卡的段落居中只移动文字，先理解段落格式才能与整表对象居中区分。"},{"id":"y2020q60","label":"给表格设置全部框线","reason":"表格格式操作依赖选区与应用范围，整表和所选单元格不能混为一谈。"}]},{"q":69,"target":null,"chapter":3,"section":"3.4","topic":"链接与嵌入","title":"链接Excel表格可随源数据更新，嵌入保留独立副本","conclusion":"希望Word表格跟随Excel变化，应采用粘贴链接或链接对象；普通粘贴、嵌入和图片通常不会自动跟随源文件。","points":["复制Excel区域后，在Word选择“链接并保留源格式”或“链接并使用目标样式”；也可用开始→粘贴→选择性粘贴→粘贴链接。","更新链路：修改并保存Excel源数据→Word刷新链接或按提示更新→核对Word中的值。更新时机仍受自动更新和安全设置影响。","链接依赖源文件位置和访问权限；移动、重命名或失去权限可能使更新失败。Word暂时还能显示旧值，不代表链接正常。","源格式/目标格式决定外观，链接/嵌入决定数据关系；两者要分别判断。"],"boundary":"链接是数据关系，源格式/目标格式是外观选择，两者不是同一个维度。","type":"综合","trigger":"从链接与嵌入的判断与应用整理。","id":"y2022q69","sources":[{"year":2022,"q":69,"type":"综合"}],"keys":["2022-69"],"comparison":{"headers":["粘贴方式","源Excel修改后","Word里保存什么"],"rows":[["粘贴链接","允许并刷新后可更新","链接关系及显示内容"],["嵌入Excel对象","不跟随源文件变化","可独立编辑的Excel副本"],["普通表格粘贴","不跟随源文件变化","Word表格内容"],["图片","不跟随源文件变化","图像，不能按单元格修改"]]},"related":[{"id":"y2021q9","label":"跨工作簿引用要指明工作簿和工作表","reason":"跨文件链接都依赖源位置和更新状态，看到旧缓存值不能证明源文件已同步。"},{"id":"merged-12","label":"保留图表结构才能按系列或类别动画","reason":"保留链接关系、可编辑对象结构和源格式是不同选择，也影响PowerPoint图表的更新与动画。"}],"pointGroups":[{"title":"先选数据关系与粘贴外观","indices":[0,3]},{"title":"更新链接并排查源文件依赖","indices":[1,2]}]},{"q":6,"chapter":3,"section":"3.4","type":"单选","topic":"删除表格","title":"Word表格的转换、计算、排序与删除","trigger":"真题反复辨析选中整张Word表格后Delete与Backspace的不同结果。","conclusion":"选中整张表格后按Delete通常只清空单元格内容并保留结构；按Backspace或使用“删除表格”命令可删除结构。","points":["选择整表：使用表格左上角移动控点。按Delete通常只清空内容；明确删除表格结构可用表格工具→布局→删除→删除表格。整表确已选中时，Backspace也可删除表格。","文本转表格：插入→表格→文本转换成表格。用制表符、逗号等分隔列，用段落标记分隔行；先核对每行分隔符数量和目标列数。","排序：表格工具→布局→数据→排序。指定主要关键字、数据类型、升降序及有无标题行；文字可按可用的拼音、笔划等规则排序。","计算：把光标放入结果单元格，再用表格工具→布局→公式。=SUM(ABOVE)用于上方，=SUM(LEFT)用于左方；需精确范围时也可使用单元格引用。","Word表格公式是域。源数值修改后，应选择结果按F9或右击更新域，不能假定会像Excel一样立即重算。使用位置参数求和时，参与范围中的空单元格可先填0，避免范围或结果异常。"],"boundary":"同样一个Delete或Backspace，光标、文字选区、单元格选区与整表选区会得到不同结果；先确认选中了什么。","id":"y2024q8","sources":[{"year":2023,"q":6,"type":"单选"},{"year":2024,"q":8,"type":"单选"}],"keys":["2023-6","2024-8"],"related":[{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"Word表格公式与题注、交叉引用同样使用域，源内容改变后要核对并更新域。"},{"id":"y2024q10","label":"清除内容只移除值或公式，不清除格式","reason":"Word表格和Excel单元格的Delete通常清空内容，删除结构需使用对应删除操作。"},{"id":"y2021q47","label":"导入CSV时明确分隔符和列类型，保住长编号","reason":"文本转表格和CSV导入都要先确认分隔符与字段结构，不能只按视觉间距判断列。"}],"pointGroups":[{"title":"清空内容与删除表格结构","indices":[0]},{"title":"按分隔符转换并按字段排序","indices":[1,2]},{"title":"计算公式及更新域的条件","indices":[3,4]}]},{"q":45,"chapter":3,"section":"3.5","type":"操作","topic":"图片尺寸","title":"图片尺寸、纵横比与裁剪","trigger":"两道连续操作题考查为何宽高不能同时指定，以及如何在尺寸要求和不变形之间取舍。","conclusion":"锁定纵横比时修改一边会按比例改变另一边；需要精确尺寸且不失真时，应先裁剪到目标比例再缩放。","points":["关闭纵横比可以强制输入宽高，但可能拉伸图像。","裁剪改变可见范围，缩放改变显示尺寸，两者解决的问题不同。","实际排版应优先保持人物和图形不变形。","2020年题设原图高8.5 cm、宽6 cm。锁定比例后，高改为6 cm时宽约4.24 cm；宽改为5 cm时高约7.08 cm。目标高6 cm、宽5 cm的宽高比为5∶6，与原图6∶8.5不同。"],"boundary":"考试若只问机械步骤可能选择取消锁定；规范成品还要检查是否产生视觉失真。","id":"merged-9","sources":[{"year":2020,"q":45,"type":"操作"},{"year":2020,"q":46,"type":"操作"}],"keys":["2020-45","2020-46"],"related":[{"id":"y2024q66","label":"固定行距过小会裁切嵌入型图片","reason":"图片看起来缺一块可能来自固定行距裁切，应先排除排版原因再改图像尺寸。"},{"id":"y2026q53","label":"更改图片可保留对象的大部分效果","reason":"替换图片后要重新检查纵横比和裁剪，保留对象效果不保证新图片构图合适。"}]},{"q":54,"target":null,"chapter":3,"section":"3.5","topic":"艺术字","title":"用艺术字创建弯曲、描边和填充的装饰文字","conclusion":"艺术字是可编辑的文字对象，可设置文字填充、轮廓和文字效果；弯曲文字应使用文字效果中的转换。","points":["“插入→艺术字”创建对象并输入文字。","选中艺术字后，在绘图工具格式中调整文字效果；跟随路径/转换改变文字排列形态。","普通字符加粗或放大不会让整段文字沿弧线排列。"],"boundary":"文字效果与形状效果不同；艺术字仍可改文字，转成图片后不再是同一编辑对象。","type":"操作","trigger":"从艺术字的判断与应用整理。","id":"y2022q54","sources":[{"year":2022,"q":54,"type":"操作"}],"keys":["2022-54"],"related":[{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"艺术字可与图片、形状组合，但要选对象外框，不能停留在文字编辑状态。"},{"id":"y2024q26","label":"艺术字是可旋转、填充和组合的图形对象","reason":"PowerPoint艺术字同样保留文字填充、旋转与组内编辑能力，可迁移对象选择思路。"}]},{"q":7,"chapter":3,"section":"3.5","type":"单选","topic":"公式工具","title":"Word公式应从“插入→公式”创建和编辑","trigger":"题目辨析Word 2016公式工具的入口、显示方式和结构编辑。","conclusion":"Word 2016应通过“插入→公式”或Alt+=插入公式，随后在公式工具中搭建分数、上下标、根式等结构。","points":["公式既可与正文位于同一行，也可转换为独立显示。","选中已有公式后可继续修改结构、符号与专业/线性显示。","常用公式可以保存到公式库重复使用。","保存为Word 97—2003的.doc时，内置公式会转换为不可直接编辑的图像形式。需要继续编辑公式结构，优先保留.docx；不能把所有看得见的公式都认作可进入公式工具的对象。"],"boundary":"“插入→对象”可嵌入某些对象，但不是Word内置公式工具的标准入口。","id":"y2023q7","sources":[{"year":2023,"q":7,"type":"单选"}],"keys":["2023-7"],"related":[{"id":"merged-7","label":"显示、字符格式与段落对齐要分清","reason":"字符上下标只改选中文字位置；分数、根式等复杂结构应使用内置公式对象。"},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"需要给公式编号并在正文引用时，应使用题注和交叉引用保持对应关系。"}],"pointGroups":null},{"q":53,"chapter":3,"section":"3.5","type":"操作","topic":"图片环绕","title":"图片环绕取决于对象是嵌入型还是浮动型","trigger":"真题从环绕菜单入口和版面结果考查图片与正文关系。","conclusion":"嵌入型把图片当成文本行里的字符；其他环绕方式让图片成为锚定到段落的浮动对象。先确定是否要绕排，再选环绕边界。","points":["先选中图片，再从图片工具→格式→环绕文字或图片旁的布局选项设置。嵌入型不能像浮动对象一样随意拖到正文任意位置。","四周型按外接矩形绕排；紧密型、穿越型依据环绕轮廓。图片背景、透明区和编辑环绕顶点会影响效果，不能只凭图片外形名称判断。","浮动图片还要区分“随文字移动”和“在页面上固定位置”；环绕方式与位置关系是两个设置，改变前者不等于自动锁定后者。"],"boundary":"文字出现在图片左右两侧可排除嵌入型和上下型；仅凭一张矩形截图，可能无法唯一分辨四周型与紧密型。","id":"y2025q47","sources":[{"year":2024,"q":53,"type":"操作"},{"year":2025,"q":47,"type":"操作"},{"year":2022,"q":52,"type":"操作"},{"year":2021,"q":7,"type":"单选","page":2}],"keys":["2024-53","2025-47","2022-52","2021-7"],"comparison":{"headers":["环绕方式","文字如何排布"],"rows":[["嵌入型","图片像一个字符占据文本行"],["四周型","围绕图片外接矩形"],["紧密型","贴近可用的环绕轮廓"],["穿越型","可进入环绕轮廓允许的内部空隙"],["上下型","只在图片上方、下方排文字"],["衬于文字下方","文字覆盖在图片上方"],["浮于文字上方","图片可能遮住正文"]]},"related":[{"id":"y2024q66","label":"固定行距过小会裁切嵌入型图片","reason":"嵌入型图片占文本行，若显示不全应检查段落固定行距。"},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"组合多个对象前，嵌入型图片通常须先改成可共同选择的非嵌入型对象。"},{"id":"y2025q56","label":"对象叠放顺序决定箭头是否被形状遮挡","reason":"文字环绕管对象与正文的关系，两个浮动对象谁遮挡谁则由叠放顺序控制。"}]},{"q":56,"chapter":3,"section":"3.5","type":"分析","topic":"对象层级","title":"对象叠放顺序决定箭头是否被形状遮挡","trigger":"两道连续分析题先判断遮挡原因，再要求用绘图工具修复。","conclusion":"浮动对象按层级叠放；矩形位于箭头上层时会遮挡箭头，把箭头置于顶层即可修复。","points":["选择窗格可查看并重排对象层级。","置于顶层或把遮挡对象置于底层都能改变可见关系。","调整层级不会改变对象尺寸和位置。"],"boundary":"文字环绕控制对象与正文的关系，不负责两个浮动形状之间的前后层级。","id":"y2025q56","sources":[{"year":2025,"q":56,"type":"分析"},{"year":2025,"q":57,"type":"分析"}],"keys":["2025-56","2025-57"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"改变对象与正文的环绕关系，不能代替两个浮动形状之间的层级调整。"},{"id":"y2026q36","label":"形状可以与图片、艺术字组合","reason":"对象组合后仍可进入组内选择和编辑，必要时先定位被遮挡的成员。"}]},{"q":36,"chapter":3,"section":"3.5","type":"判断","topic":"图形组合","title":"形状可以与图片、艺术字组合","trigger":"题目判断Word中的形状能否与图片或艺术字组合成整体。","conclusion":"形状、图片、艺术字可作为一个组整体操作。先把图片设为非嵌入型环绕，按Ctrl选择至少两个可组合对象，再使用组合命令。","points":["按住Ctrl逐个选择对象外框；点击对象内部文字会进入文字编辑，不能代替选中对象。","入口：图片工具→格式，或绘图工具→格式→排列→组合→组合。按钮不可用时，先检查是否至少选中两个对象，并逐个确认环绕方式都不是嵌入型；这个条件不只针对图片，也适用于可设置环绕的形状和艺术字。","组合后可统一移动、缩放和旋转；先选组合再选其中对象，仍可修改组内对象，也可取消组合后分别编辑。","对象还应处于可共同选择的文档区域；正文对象与页眉中的对象不能直接当作同一组选择。"],"boundary":"组合不等于合并成一张位图，不会自动删除原对象的可编辑属性；不同对象类型仍有各自限制。","id":"y2026q36","sources":[{"year":2026,"q":36,"type":"判断"}],"keys":["2026-36"],"related":[{"id":"y2025q47","label":"图片环绕取决于对象是嵌入型还是浮动型","reason":"嵌入型图片按字符排布，组合前需理解并调整它的环绕方式。"},{"id":"y2025q56","label":"对象叠放顺序决定箭头是否被形状遮挡","reason":"组合管理整体操作，叠放顺序管理前后遮挡；组合本身不会自动修正可见关系。"}],"pointGroups":null},{"q":71,"target":null,"chapter":3,"section":"3.6","topic":"限制编辑","title":"只锁表格、保留正文可编辑，需要设置编辑例外","conclusion":"Word的限制编辑可设为只读，再把允许修改的正文设置为例外，使表格仍处于受保护区域。","points":["“审阅→限制编辑→仅允许此类型编辑→不允许任何更改（只读）”。","选中允许改动的正文，并设置例外用户；不要把需保护的表格加入例外。","启动强制保护后再测试：正文可改、表格不可改。需密码时妥善保管。"],"boundary":"打开密码控制能否打开文档，不等于按区域限制修改；只选中表格并没有独立的“保护表格”密码命令。","type":"综合","trigger":"从限制编辑的判断与应用整理。","id":"y2022q71","sources":[{"year":2022,"q":71,"type":"综合"}],"keys":["2022-71"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"Word区域限制编辑与文件属性、目录权限属于不同层级，不能用只读属性替代正文例外。"},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"限制编辑决定能否修改，修订决定如何记录与处理修改，两者解决不同协作问题。"}]},{"q":5,"chapter":3,"section":"3.7","type":"单选","topic":"题注与引用","title":"题注与交叉引用要配合使用","trigger":"真题从自动表号、图表编号和“先题注、后引用”的操作顺序考查长文档引用。","conclusion":"先为图、表或公式插入题注，再在正文中用交叉引用插入编号，才能在对象增删后统一更新。","points":["为图、表或公式设置自动题注：选择对象→引用→插入题注，确定标签、编号格式和位置；题注编号由域管理。","正文引用图号：引用→交叉引用，选择对应题注及所需内容，例如“仅标签和编号”。选为超链接可支持跳转，但跳转选项不是编号关系本身。","新增、删除或移动对象后，先更新题注编号，再更新引用它的交叉引用域；可选择相关域按F9。跨不同文档区域时要分别核对。","题注还可用于生成图表目录；手工输入的“表1”只是一段普通文字，不会建立自动题注、交叉引用和图表目录的关联。"],"boundary":"自动题注管理对象编号，交叉引用引用已有目标；这两个步骤缺一时，正文编号都可能与对象不一致。","version":"已转换为Word 2016","id":"merged-6","sources":[{"year":2020,"q":5,"type":"单选"},{"year":2023,"q":54,"type":"操作"},{"year":2026,"q":48,"type":"操作"},{"year":2021,"q":6,"type":"单选","page":2}],"keys":["2020-5","2023-54","2026-48","2021-6"],"related":[{"id":"merged-5","label":"Word视图、标题结构与导航窗格","reason":"自动目录依赖标题，图表目录依赖题注；先建立结构再生成目录，手输编号不够。"},{"id":"y2024q8","label":"Word表格的转换、计算、排序与删除","reason":"Word表格公式也是域，可与题注引用一起理解源内容变化后的更新操作。"},{"id":"y2022q55","label":"脚注在页底，尾注通常在文末或节末","reason":"题注给图表编号，脚注补充说明，先按用途选择对象再插入引用。"}],"pointGroups":[{"title":"建立题注与正文交叉引用","indices":[0,1]},{"title":"增删对象后更新并生成图表目录","indices":[2,3]}]},{"q":55,"target":null,"chapter":3,"section":"3.7","topic":"脚注与尾注","title":"脚注在页底，尾注通常在文末或节末","conclusion":"脚注和尾注由正文引用标记连接说明内容；插入引用后由Word管理编号。","points":["光标放在需解释的文字后，使用“引用→插入脚注”。","新增、移动或删除正文中的引用标记时，编号可自动重新安排。","脚注/尾注用于补充说明；批注用于审阅交流，题注用于给图表编号。"],"boundary":"删除注释应删除正文中的引用标记，不能只擦掉页底说明文字。","type":"操作","trigger":"从脚注与尾注的判断与应用整理。","id":"y2022q55","sources":[{"year":2022,"q":55,"type":"操作"}],"keys":["2022-55"],"related":[{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"脚注引用连接说明，交叉引用连接题注目标，均应管理引用关系而非手工写显示编号。"},{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"脚注属于正文的补充说明，批注用于审阅交流，二者在交付文本中的角色不同。"}]},{"q":56,"chapter":3,"section":"3.7","type":"操作","topic":"修订","title":"修订记录编辑，接受或拒绝决定最终文本","trigger":"题目要求按正确顺序记录教师的插入、删除并形成最终稿。","conclusion":"先打开“审阅→修订”，再进行编辑；完成后逐项接受或拒绝修订，才能形成最终文本。","points":["开始记录：审阅→修订，再编辑正文；插入、删除和格式更改会作为修订保留。关闭修订只停止记录之后的编辑。","所有标记用于查看完整修订；无标记暂时显示采用修订后的清洁效果，但修订记录仍保存在文档中。","接受插入会保留新增文字，拒绝插入会去掉新增文字；接受删除会真正去掉原文字，拒绝删除会恢复原文字。","批注用于说明与讨论，不直接改正文；比较文档用于找出两个版本的差异，与预先开启修订记录后续操作不同。","交付最终文本前，核对并接受或拒绝已有修订。需要停止记录时再关闭修订；不要只切到无标记就认定清理完成。"],"boundary":"是否记录新修改、是否显示旧记录、是否接受旧修改是三件事；隐藏显示不能代替处理修订。","id":"y2023q56","sources":[{"year":2023,"q":56,"type":"操作"},{"year":2021,"q":8,"type":"单选","page":3}],"keys":["2023-56","2021-8"],"related":[{"id":"y2022q71","label":"只锁表格、保留正文可编辑，需要设置编辑例外","reason":"开启修订不等于限制修改权限，若需正文可改而表格受保护，还要设置编辑例外。"},{"id":"y2023q55","label":"校对波浪线提示可能的问题，不属于打印正文","reason":"编辑提示和审阅标记均可被隐藏，但隐藏不意味着错误已改正或修订已接受。"}],"pointGroups":[{"title":"记录新修改与显示旧修订","indices":[0,1]},{"title":"接受或拒绝并完成最终文本","indices":[2,4]},{"title":"批注和比较文档解决什么问题","indices":[3]}]},{"q":55,"chapter":3,"section":"3.7","type":"操作","topic":"页码域","title":"在形状中放置光标后插入PAGE域","trigger":"题目要求把页码显示在页眉中的平行四边形形状内。","conclusion":"先进入页眉并在形状文字区内放置插入点，再用“页码→当前位置”或插入PAGE域，页码才会成为形状内的动态内容。","points":["“页面顶端”图库会在预设页眉位置新建页码对象，不保证进入现有形状。","PAGE域显示当前页码，NUMPAGES域显示总页数。","页眉中的形状会随页眉重复，但节之间可有不同设置。","用域代码插入时，在形状文字区按Ctrl+F9建立域括号，输入PAGE后按F9更新；若显示的是代码，可按Shift+F9切换当前域的代码与结果。直接键入“{ PAGE }”只是文字，不会生成页码域。"],"boundary":"先选中形状外框与把光标放进形状文字区是不同状态；只有后者能把页码插到形状内部。","id":"y2024q55","sources":[{"year":2024,"q":55,"type":"操作"}],"keys":["2024-55"],"related":[{"id":"y2020q41","label":"页眉由节、链接状态与首页/奇偶页选项共同决定","reason":"PAGE域显示的页码仍受当前节的起号、页眉页脚类型及链接状态影响。"},{"id":"merged-6","label":"题注与交叉引用要配合使用","reason":"自动页码、题注和交叉引用都由域生成动态内容，不能用手输数字替代。"}],"pointGroups":null},{"q":36,"chapter":3,"section":"3.7","type":"判断","topic":"邮件合并","title":"邮件合并连接数据源，合并域和条件规则生成个性化文档","trigger":"题目判断Word 2016邮件合并的数据源能否选择Word文档。","conclusion":"主文档保存共同内容，数据源按行保存记录，合并域把字段放进指定位置；条件规则可按记录内容生成不同称谓。","points":["数据源可以来自规范的Word表格、Excel、Access、Outlook联系人或文本列表；首行通常是字段名，每条记录对应一个收件人或数据对象。","在邮件→选择收件人→使用现有列表连接数据源，确认表或工作表、字段名及所需收件人，再插入姓名等合并域。","需要按性别生成称谓时，用邮件→规则→如果…那么…否则。字段、比较值和两种输出都要设置，例如性别等于“女”输出“女士”，否则输出“先生”。","预览结果后切换记录，检查姓名、称谓和空缺字段；预览只显示当前记录效果。完成并合并时再选择生成文档、打印或其他合并目标。","生成结果不等于原数据源被改写；也不要把所有收件人的内容手工堆在主文档中。"],"boundary":"数据源需要规则的字段和记录；普通散排正文不能直接替代收件人表。字段值为空或拼写不一致时，条件规则可能走到另一分支。","id":"y2025q36","sources":[{"year":2025,"q":36,"type":"判断"},{"year":2022,"q":56,"type":"操作"}],"keys":["2025-36","2022-56"],"related":[{"id":"y2021q47","label":"导入CSV时明确分隔符和列类型，保住长编号","reason":"收件人表中的长编号须在导入时保留文本类型，精度丢失后邮件合并不能还原。"},{"id":"y2021q50","label":"先提取一位，再判奇偶，最后选择输出","reason":"“如果…那么…否则”与IF同样按条件选择输出，字段值和真、假分支需逐项核对。"},{"id":"y2024q59","label":"格式化为表格同时建立结构化数据区域","reason":"Excel来源需规范列标题与明细记录，建表时核对标题行，可减少姓名等合并字段识别错误。"}],"pointGroups":[{"title":"规范数据源并连接合并域","indices":[0,1]},{"title":"按记录条件选择称谓","indices":[2]},{"title":"逐条预览并生成合并结果","indices":[3,4]}]},{"id":"syllabus-document-coauthor","chapter":3,"section":"3.7","origin":"syllabus","topic":"考纲补充","title":"共同编辑、批注和修订是三种不同协作动作","conclusion":"共同编辑让多人修改同一份共享文档；批注提出问题或意见；修订记录文字的增删改，等待接受或拒绝。发送多个附件副本会形成多份文件，并不等于共同编辑。","points":["Word 2016示例：先把文档保存到OneDrive或SharePoint Online，选择“共享”，核对参与者与可查看/可编辑权限，再把同一文档的链接交给参与者。","协作时观察他人的编辑位置，避免同时改写同一段；用批注讨论，用修订保留需要审阅的改动。结束前核对保存/同步状态与最终版本。","使用在线协作软件时，应核对账号、共享范围和权限；能打开文档不代表有编辑权。版本历史与修订记录用途不同，恢复旧版本后仍需检查是否覆盖了他人的有效修改。"],"boundary":"协同功能受文件格式、保存位置、客户端和账号配置影响；不要把Word 2016的能力直接推广到所有Office 2016组件。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2023q56","label":"修订记录编辑，接受或拒绝决定最终文本","reason":"联系相邻知识理解作用范围"}]},{"id":"syllabus-office-exchange","chapter":3,"section":"3.1","origin":"syllabus","topic":"考纲补充","title":"编辑源文件、纯文本和固定版面文档各有用途","conclusion":"DOCX适合保留Word文档的结构、样式和对象供继续编辑；TXT主要保存纯文本，不保留复杂排版；PDF常用于保持页面外观、阅读或打印。","points":["DOC是较早的Word格式；RTF支持一定的文本格式交换。选择交换格式前，应看对方需要继续编辑、保留结构还是核对固定版面。","WPS Office也提供文字、表格和演示工具；跨软件打开文件后，应检查字体、分页、公式、图表、动画等关键结果，不能仅凭扩展名相同就保证完全一致。","Word、WPS文字适合连续文稿、样式、目录和页面排版；Excel、WPS表格适合按行列组织数据、公式计算、筛选汇总与图表；PowerPoint、WPS演示适合按幻灯片组织讲解。","教学示例：班级成绩录入和平均分计算放在表格软件；分析报告放在文字软件；面向全班展示结论使用演示软件。报告中的表格不因此等同于Excel工作簿。","先新建相应类型文件，再按需要保存可编辑源文件。Office常用源格式分别是DOCX、XLSX、PPTX；跨软件交换后检查字体、公式、图表和动画是否保持。"],"boundary":"这里是文档常见格式的教学概括；兼容情况取决于具体版本和文件使用的功能。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2021q56","label":"样式统一一份文档，模板给多份文档共同起点","reason":"联系相邻知识理解作用范围"}],"pointGroups":[{"title":"已有知识","indices":[0,1]},{"title":"先按任务选文字、表格或演示软件","indices":[2,3,4]}]},{"id":"syllabus-word-smartart","chapter":3,"section":"3.5","origin":"syllabus","topic":"考纲补充","title":"Word用SmartArt表达步骤或层级","conclusion":"SmartArt把文字组织成流程、层次或关系图。先判断要表达的关系，再选布局；三步办事流程适合流程布局，部门隶属关系适合层次布局。","points":["Word 2016教学示例：插入→插图→SmartArt→流程，选择合适布局，在文本窗格依次输入“登记、审核、归档”。","要增加步骤，先选相邻形状，再到SmartArt工具→设计→添加形状，选择前方或后方；要改全部配色，选SmartArt后更改颜色。先分清选中文字、单个形状还是整幅图。"],"boundary":"SmartArt保持可编辑的结构；把流程截图后插入只得到图片，不能再按SmartArt步骤编辑。","sources":[],"trigger":"依据2026年官方考试要求补充；示例用于解释操作与原理，不标为历史原题。","related":[{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"对照相邻概念，检查作用范围"}]},{"id":"syllabus-word-screen-clipping","chapter":3,"section":"3.5","origin":"syllabus","topic":"考纲补充","title":"Word截图可插入完整窗口或局部区域","conclusion":"先打开要截取的程序窗口且不要将其最小化，再把Word光标放到插入位置，选择插入→插图→屏幕截图。","points":["在“可用视窗”点缩略图可插入整个窗口；选择“屏幕剪辑”后拖出矩形区域，可只截需要的一部分。","教学示例：为实验报告加入设置对话框，只截对话框内容，插入后再调图片大小与环绕。屏幕截图是画面快照，源窗口后来改变时它不会自动同步。"],"boundary":"截图中的文字通常仍是图片像素，不自动变成可编辑正文；未最小化是可用视窗捕获的条件。","sources":[],"trigger":"依据2026年官方考试要求补充；示例用于解释操作与原理，不标为历史原题。","related":[{"id":"merged-9","label":"图片尺寸、纵横比与裁剪","reason":"对照相邻概念，检查作用范围"}]},{"id":"syllabus-word-print-controls","chapter":3,"section":"3.6","origin":"syllabus","topic":"考纲补充","title":"打印先定范围，再定份数、纸面和标记","conclusion":"文件→打印先预览，再选打印机、份数和打印范围。普通连续页码可写2-4；要打印第2页及第5至7页，可写2,5-7。分节重新编号时应核对预览，不能只凭页码外观推断物理页。","points":["单面/双面控制纸张两面的使用方式；自动双面需要打印机支持，手动双面按提示重新放纸。先用少量页面测试翻纸方向。","含修订或批注的文档，要在打印设置核对“打印标记”，并用预览确认输出是否带标记；不打印标记并不等于已接受全部修订。","教学示例：打印两份第2至4页、不带批注的报告，应分别设置份数2、范围2-4及标记选择，再检查预览。"],"boundary":"份数、页码范围、每张纸页数和单双面是不同设置；不要用其中一项替代另一项。","sources":[],"trigger":"依据2026年官方考试要求补充；示例用于解释操作与原理，不标为历史原题。","related":[{"id":"y2022q71","label":"只锁表格、保留正文可编辑，需要设置编辑例外","reason":"对照相邻概念，检查作用范围"}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
